import Foundation

public enum CaptureBundleSchemaRegistry {
    /// Maps a logical bundle path to its published schema name.
    /// Frame descriptors live at evidence/frames/<frame-id>.json.
    public static func schemaName(forPath path: String) -> String? {
        switch path {
        case "manifest.json":
            return "manifest"
        case "session/capture-session.json":
            return "session"
        case "session/device.json":
            return "device"
        case "session/capabilities.json":
            return "capabilities"
        case "session/capture-configuration.json":
            return "capture-configuration"
        case "session/timing.json":
            return "timing"
        case "mesh/anchors.json":
            return "mesh-anchors"
        case "annotations/entities.json":
            return "entities"
        case "annotations/measurements.json":
            return "measurements"
        case "quality/capture-quality.json":
            return "quality"
        default:
            let components = path.split(
                separator: "/",
                omittingEmptySubsequences: false
            )
            if components.count == 3,
               components[0] == "evidence",
               components[1] == "frames",
               components[2].hasSuffix(".json"),
               components[2].count > 5
            {
                return "frame"
            }
            return nil
        }
    }

    public static func compiledSchema(
        named name: String
    ) throws -> CompiledJSONSchema {
        let registry = try compiled.get()
        guard let schema = registry[name] else {
            throw JSONSchemaError.unknownSchema(name)
        }
        return schema
    }

    private static let compiled: Result<[String: CompiledJSONSchema], JSONSchemaError> = {
        do {
            var registry: [String: CompiledJSONSchema] = [:]
            for (name, source) in documents {
                let parsed = try StrictJSON.parse(Data(source.utf8))
                registry[name] = try JSONSchemaValidator.compile(parsed)
            }
            return .success(registry)
        } catch let error as JSONSchemaError {
            return .failure(error)
        } catch {
            return .failure(.invalidKeywordValue("schema document"))
        }
    }()

